window.OWN_BUNDLES=window.OWN_BUNDLES||{};window.OWN_BUNDLES["apple"]={html:"<div class=\"own-apple\">\n  <header class=\"ap-global\">\n    <a class=\"ap-global-mark\" href=\"#ap-top\" aria-label=\"Northwind home\">\n      <svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M12 3 4 6v6c0 4.4 3.2 8 8 9 4.8-1 8-4.6 8-9V6l-8-3Z\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\"/><path d=\"M8.5 12l2.4 2.4L15.5 9.5\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></svg>\n    </a>\n    <nav class=\"ap-global-menu\" aria-label=\"Northwind\">\n      <a href=\"#ap-store\">Overview</a>\n      <a href=\"#ap-dark\">Regions</a>\n      <a href=\"#ap-grid\">Boards</a>\n      <a href=\"#ap-config\">Configure</a>\n      <a href=\"#ap-foot\">Support</a>\n    </nav>\n    <div class=\"ap-global-right\">\n      <button class=\"ap-ico\" type=\"button\" aria-label=\"Search\"><svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><circle cx=\"11\" cy=\"11\" r=\"7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\"/><path d=\"m20 20-4-4\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\"/></svg></button>\n      <button class=\"ap-ico\" type=\"button\" aria-label=\"Bag\"><svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M6 8h12l-1 12H7L6 8Z\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.6\"/><path d=\"M9 8a3 3 0 0 1 6 0\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.6\"/></svg></button>\n    </div>\n  </header>\n\n  <div class=\"ap-subnav\">\n    <span class=\"ap-subnav-name\">Northwind Ops</span>\n    <nav class=\"ap-subnav-links\" aria-label=\"Section\">\n      <a href=\"#ap-grid\">Boards</a>\n      <a href=\"#ap-config\">Plans</a>\n      <a href=\"#ap-foot\">Support</a>\n    </nav>\n    <a class=\"ap-btn ap-btn-primary ap-btn-sm\" href=\"#ap-config\">Start free trial</a>\n  </div>\n\n  <main id=\"ap-top\">\n    <section class=\"ap-tile ap-tile-light\" aria-labelledby=\"ap-h1\">\n      <p class=\"ap-kicker\">Northwind Ops</p>\n      <h1 id=\"ap-h1\" class=\"ap-hero\">Every region.<br>One board.</h1>\n      <p class=\"ap-tagline\">Production operations in prototype speed.</p>\n      <div class=\"ap-tile-cta\">\n        <a class=\"ap-btn ap-btn-primary\" href=\"#ap-config\">Start free trial</a>\n        <a class=\"ap-link\" href=\"#ap-grid\">Learn more <span aria-hidden=\"true\">›</span></a>\n      </div>\n      <div class=\"ap-render ap-render-light\" aria-hidden=\"true\">\n        <div class=\"ap-screen\">\n          <div class=\"ap-screen-top\"><span class=\"ap-dot\"></span><span class=\"ap-dot\"></span><span class=\"ap-dot\"></span><span class=\"ap-screen-title\">Operations · live</span></div>\n          <div class=\"ap-screen-grid\">\n            <div class=\"ap-screen-kpi\"><b>98.1%</b><span>on-time</span></div>\n            <div class=\"ap-screen-kpi\"><b>412k</b><span>units / day</span></div>\n            <div class=\"ap-screen-kpi\"><b>$2.41</b><span>cost / unit</span></div>\n          </div>\n          <svg class=\"ap-screen-chart\" viewBox=\"0 0 320 70\" preserveAspectRatio=\"none\" aria-hidden=\"true\">\n            <polyline points=\"0,54 45,44 90,50 135,30 180,34 225,20 270,24 320,12\" fill=\"none\" stroke=\"#0066cc\" stroke-width=\"3\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/>\n          </svg>\n        </div>\n      </div>\n    </section>\n\n    <section id=\"ap-dark\" class=\"ap-tile ap-tile-dark\" aria-labelledby=\"ap-dark-h\">\n      <h2 id=\"ap-dark-h\" class=\"ap-tile-h\">Line yield, watched every shift</h2>\n      <p class=\"ap-tagline ap-tagline-dark\">Six regions, fourteen lines, one governed model.</p>\n      <div class=\"ap-tile-cta\">\n        <a class=\"ap-btn ap-btn-primary\" href=\"#ap-grid\">See the boards</a>\n        <a class=\"ap-link ap-link-dark\" href=\"#ap-config\">Compare plans <span aria-hidden=\"true\">›</span></a>\n      </div>\n      <div class=\"ap-render ap-render-dark\" aria-hidden=\"true\">\n        <div class=\"ap-grid-mock\">\n          <span class=\"ap-cell ap-cell-a\"></span><span class=\"ap-cell ap-cell-b\"></span><span class=\"ap-cell ap-cell-c\"></span>\n          <span class=\"ap-cell ap-cell-b\"></span><span class=\"ap-cell ap-cell-a\"></span><span class=\"ap-cell ap-cell-c\"></span>\n          <span class=\"ap-cell ap-cell-c\"></span><span class=\"ap-cell ap-cell-a\"></span><span class=\"ap-cell ap-cell-b\"></span>\n        </div>\n      </div>\n    </section>\n\n    <section id=\"ap-store\" class=\"ap-tile ap-tile-parchment\" aria-labelledby=\"ap-store-h\">\n      <div class=\"ap-store-head\">\n        <h2 id=\"ap-store-h\" class=\"ap-tile-h\">The boards teams keep open</h2>\n        <p class=\"ap-store-sub\">A live fragment of the floor in every card.</p>\n      </div>\n      <div class=\"ap-store-grid\" id=\"apStoreGrid\"></div>\n    </section>\n\n    <section id=\"ap-grid\" class=\"ap-tile ap-tile-light\" aria-labelledby=\"ap-metrics-h\">\n      <h2 id=\"ap-metrics-h\" class=\"ap-tile-h\">Numbers that agree, every shift</h2>\n      <p class=\"ap-tagline\">The same rows the night shift sees, refreshed every fifteen minutes.</p>\n      <div class=\"ap-metric-row\">\n        <div class=\"ap-metric\"><b>316,258</b><span>units tracked daily</span></div>\n        <div class=\"ap-metric\"><b>12</b><span>regions on one board</span></div>\n        <div class=\"ap-metric\"><b>$429M</b><span>value recovered</span></div>\n        <div class=\"ap-metric\"><b>99.98%</b><span>model uptime</span></div>\n      </div>\n    </section>\n\n    <section id=\"ap-config\" class=\"ap-tile ap-tile-light ap-tile-config\" aria-labelledby=\"ap-config-h\">\n      <div class=\"ap-config-copy\">\n        <h2 id=\"ap-config-h\" class=\"ap-tile-h\">Pick a plan. Add regions.</h2>\n        <p class=\"ap-tagline\">Start on the operations tier and expand per region. No card for the first 30 days.</p>\n        <div class=\"ap-config-price\"><span class=\"ap-config-amount\" id=\"apAmount\">$4,900</span><span class=\"ap-config-unit\">/ month</span></div>\n        <button class=\"ap-btn ap-btn-primary\" type=\"button\">Add to plan</button>\n        <ul class=\"ap-config-list\">\n          <li>Up to 40 seats included</li>\n          <li>Unlimited boards and regions</li>\n          <li>Scheduled digests to the ops desk</li>\n        </ul>\n      </div>\n      <div class=\"ap-config-chips\" id=\"apConfigChips\" role=\"radiogroup\" aria-label=\"Regions included\"></div>\n    </section>\n  </main>\n\n  <footer id=\"ap-foot\" class=\"ap-footer\">\n    <div class=\"ap-foot-cols\">\n      <div class=\"ap-foot-col\"><h3>Shop &amp; Learn</h3><a href=\"#\">Boards</a><a href=\"#\">Regions</a><a href=\"#\">Guardrails</a><a href=\"#\">Pricing</a></div>\n      <div class=\"ap-foot-col\"><h3>Services</h3><a href=\"#\">Northwind Cloud</a><a href=\"#\">Northwind Care</a><a href=\"#\">Ops desk</a></div>\n      <div class=\"ap-foot-col\"><h3>About</h3><a href=\"#\">Newsroom</a><a href=\"#\">Careers</a><a href=\"#\">Investors</a></div>\n      <div class=\"ap-foot-col\"><h3>For Business</h3><a href=\"#\">Enterprise</a><a href=\"#\">Security</a><a href=\"#\">Contact sales</a></div>\n    </div>\n    <div class=\"ap-legal\">\n      <span>© 2026 Northwind Analytics — sample data, showcase only. <a href=\"#\">Privacy Policy</a> · <a href=\"#\">Terms of Use</a> · <a href=\"#\">Sales</a></span>\n      <span class=\"ap-legal-right\">Philippines</span>\n    </div>\n  </footer>\n</div>\n",css:"/* ══ NORTHWIND — in the Apple design language, for showcase.html ════════════\n   Photography-first museum layout: edge-to-edge tiles alternating light /\n   parchment / near-black, SF-weight type (system-ui resolves SF Pro on Apple;\n   Inter substitute elsewhere), one Action Blue accent, exactly one product\n   shadow, negative letter-spacing at display sizes. */\n\n.own-apple {\n  --primary: #0066cc;\n  --primary-focus: #0071e3;\n  --primary-on-dark: #2997ff;\n  --ink: #1d1d1f;\n  --on-dark: #ffffff;\n  --body-muted: #cccccc;\n  --ink-muted-80: #333333;\n  --ink-muted-48: #7a7a7a;\n  --divider-soft: #f0f0f0;\n  --hairline: #e0e0e0;\n  --canvas: #ffffff;\n  --canvas-parchment: #f5f5f7;\n  --surface-pearl: #fafafc;\n  --surface-tile-1: #272729;\n  --surface-tile-2: #2a2a2c;\n  --surface-tile-3: #252527;\n  --surface-black: #000000;\n  --chip-translucent: #d2d2d7;\n  --r-xs: 5px;\n  --r-sm: 8px;\n  --r-md: 11px;\n  --r-lg: 18px;\n  --r-pill: 9999px;\n  --product-shadow: rgba(0, 0, 0, .22) 3px 5px 30px 0;\n  --font-display: 'SF Pro Display', 'Inter', system-ui, -apple-system, sans-serif;\n  --font-text: 'SF Pro Text', 'Inter', system-ui, -apple-system, sans-serif;\n  --gut: clamp(24px, 5.5cqi, 90px);\n  --section: clamp(56px, 7cqi, 80px);\n\n  position: relative;\n  background: var(--canvas);\n  color: var(--ink);\n  font-family: var(--font-text);\n  font-size: 17px;\n  line-height: 1.47;\n  letter-spacing: -.374px;\n  text-align: left;\n  border-radius: 13px;\n  overflow-x: clip;\n}\n.own-apple *, .own-apple *::before, .own-apple *::after { box-sizing: border-box; }\n.own-apple a { color: inherit; text-decoration: none; }\n.own-apple button { font: inherit; cursor: pointer; }\n.own-apple :focus-visible { outline: 2px solid var(--primary-focus); outline-offset: 2px; border-radius: 4px; }\n\n/* ── global nav (44px, true black) ────────────────────────────────────────── */\n.own-apple .ap-global { position: sticky; top: 68px; z-index: 30; display: flex; align-items: center; gap: 24px; height: 44px; padding: 0 var(--gut); background: var(--surface-black); color: var(--on-dark); }\n.own-apple .ap-global-mark { display: grid; place-items: center; color: var(--on-dark); }\n.own-apple .ap-global-mark svg { width: 20px; height: 20px; }\n.own-apple .ap-global-menu { display: flex; gap: 22px; margin: 0 auto; font-size: 12px; font-weight: 400; letter-spacing: -.12px; }\n.own-apple .ap-global-menu a { color: var(--body-muted); }\n.own-apple .ap-global-menu a:hover { color: var(--on-dark); }\n.own-apple .ap-global-right { display: flex; gap: 6px; margin-left: auto; }\n.own-apple .ap-ico { display: grid; place-items: center; width: 30px; height: 30px; border: 0; border-radius: 50%; background: transparent; color: var(--on-dark); }\n.own-apple .ap-ico:hover { background: rgba(255, 255, 255, .14); }\n.own-apple .ap-ico svg { width: 18px; height: 18px; }\n\n/* ── frosted sub-nav (52px) ───────────────────────────────────────────────── */\n.own-apple .ap-subnav { position: sticky; top: 112px; z-index: 28; display: flex; align-items: center; gap: 20px; height: 52px; padding: 0 var(--gut); background: rgba(245, 245, 247, .8); backdrop-filter: saturate(180%) blur(20px); -webkit-backdrop-filter: saturate(180%) blur(20px); border-bottom: 1px solid rgba(0, 0, 0, .08); }\n.own-apple .ap-subnav-name { font-size: 21px; font-weight: 600; letter-spacing: .231px; }\n.own-apple .ap-subnav-links { display: flex; gap: 20px; margin-left: auto; font-size: 14px; }\n.own-apple .ap-subnav-links a { color: var(--ink-muted-48); }\n.own-apple .ap-subnav-links a:hover { color: var(--ink); }\n\n/* ── buttons ──────────────────────────────────────────────────────────────── */\n.own-apple .ap-btn { display: inline-flex; align-items: center; justify-content: center; padding: 11px 22px; border: 1px solid transparent; border-radius: var(--r-pill); font-size: 17px; font-weight: 400; line-height: 1.2; transition: transform .15s ease; }\n.own-apple .ap-btn:active { transform: scale(.95); }\n.own-apple .ap-btn-primary { background: var(--primary); color: #fff; }\n.own-apple .ap-btn-primary:hover { background: var(--primary-focus); }\n.own-apple .ap-btn-sm { padding: 8px 16px; font-size: 14px; }\n.own-apple .ap-link { font-size: 17px; color: var(--primary); }\n.own-apple .ap-link:hover { text-decoration: underline; }\n.own-apple .ap-link-dark { color: var(--primary-on-dark); }\n\n/* ── tiles ────────────────────────────────────────────────────────────────── */\n.own-apple .ap-tile { padding: var(--section) var(--gut); text-align: center; display: flex; flex-direction: column; align-items: center; }\n.own-apple .ap-tile-light { background: var(--canvas); }\n.own-apple .ap-tile-parchment { background: var(--canvas-parchment); }\n.own-apple .ap-tile-dark { background: var(--surface-tile-1); color: var(--on-dark); }\n.own-apple .ap-kicker { font-size: 21px; font-weight: 600; letter-spacing: .231px; color: var(--primary); margin-bottom: 6px; }\n.own-apple .ap-hero { font-family: var(--font-display); font-size: clamp(40px, 6.6cqi, 56px); font-weight: 600; line-height: 1.07; letter-spacing: -.28px; }\n.own-apple .ap-tile-h { font-family: var(--font-display); font-size: clamp(30px, 4.6cqi, 40px); font-weight: 600; line-height: 1.1; letter-spacing: 0; }\n.own-apple .ap-tagline { font-family: var(--font-display); font-size: clamp(20px, 3cqi, 28px); font-weight: 400; line-height: 1.14; letter-spacing: .196px; margin-top: 12px; color: var(--ink); }\n.own-apple .ap-tagline-dark { color: var(--body-muted); }\n.own-apple .ap-tile-cta { display: flex; align-items: center; gap: 24px; flex-wrap: wrap; justify-content: center; margin-top: 24px; }\n\n/* product render (the one shadow in the system) */\n.own-apple .ap-render { margin-top: 56px; width: min(760px, 100%); }\n.own-apple .ap-screen { border-radius: 20px; padding: 16px; background: var(--canvas); box-shadow: var(--product-shadow); text-align: left; }\n.own-apple .ap-screen-top { display: flex; align-items: center; gap: 7px; padding-bottom: 14px; border-bottom: 1px solid var(--divider-soft); }\n.own-apple .ap-dot { width: 10px; height: 10px; border-radius: 50%; background: #e3e3e6; }\n.own-apple .ap-dot:first-child { background: #ff5f57; }\n.own-apple .ap-dot:nth-child(2) { background: #febc2e; }\n.own-apple .ap-dot:nth-child(3) { background: #28c840; }\n.own-apple .ap-screen-title { margin-left: 8px; font-size: 12px; color: var(--ink-muted-48); }\n.own-apple .ap-screen-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 12px; margin: 18px 0; }\n.own-apple .ap-screen-kpi { display: grid; gap: 2px; padding: 14px; border-radius: var(--r-md); background: var(--canvas-parchment); }\n.own-apple .ap-screen-kpi b { font-family: var(--font-display); font-size: 22px; font-weight: 600; letter-spacing: -.3px; }\n.own-apple .ap-screen-kpi span { font-size: 12px; color: var(--ink-muted-48); }\n.own-apple .ap-screen-chart { width: 100%; height: 70px; }\n\n.own-apple .ap-grid-mock { display: grid; grid-template-columns: repeat(3, 1fr); gap: 10px; padding: 22px; border-radius: 20px; background: var(--surface-tile-2); box-shadow: var(--product-shadow); }\n.own-apple .ap-cell { aspect-ratio: 1 / .6; border-radius: 10px; }\n.own-apple .ap-cell-a { background: #3a3a3d; }\n.own-apple .ap-cell-b { background: #34343a; }\n.own-apple .ap-cell-c { background: #2f2f36; }\n\n/* ── store grid (utility cards) ───────────────────────────────────────────── */\n.own-apple .ap-store-head { text-align: center; margin-bottom: 40px; }\n.own-apple .ap-store-sub { font-size: 17px; color: var(--ink-muted-48); margin-top: 10px; }\n.own-apple #apStoreGrid { width: 100%; max-width: 1180px; display: grid; grid-template-columns: repeat(4, 1fr); gap: 24px; }\n.own-apple .ap-card { display: grid; gap: 6px; padding: 24px; border: 1px solid var(--hairline); border-radius: var(--r-lg); background: var(--canvas); text-align: left; }\n.own-apple .ap-card-photo { aspect-ratio: 1 / 1; border-radius: var(--r-sm); background: var(--ph, var(--canvas-parchment)); margin-bottom: 10px; display: grid; place-items: center; }\n.own-apple .ap-card-photo span { font-family: var(--font-display); font-size: 34px; font-weight: 600; color: var(--ph-ink, #1d1d1f); letter-spacing: -.5px; }\n.own-apple .ap-card-name { font-size: 17px; font-weight: 600; }\n.own-apple .ap-card-sub { font-size: 14px; color: var(--ink-muted-48); }\n.own-apple .ap-card-price { font-size: 17px; font-weight: 400; margin-top: 4px; }\n.own-apple .ap-card-link { font-size: 14px; color: var(--primary); margin-top: 4px; }\n.own-apple .ap-card-link:hover { text-decoration: underline; }\n\n/* ── metrics ──────────────────────────────────────────────────────────────── */\n.own-apple .ap-metric-row { display: grid; grid-template-columns: repeat(4, 1fr); gap: 24px; width: 100%; max-width: 1180px; margin-top: 48px; }\n.own-apple .ap-metric { display: grid; gap: 6px; }\n.own-apple .ap-metric b { font-family: var(--font-display); font-size: clamp(30px, 4cqi, 40px); font-weight: 600; letter-spacing: -.374px; color: var(--primary); }\n.own-apple .ap-metric span { font-size: 14px; color: var(--ink-muted-48); }\n\n/* ── configurator ─────────────────────────────────────────────────────────── */\n.own-apple .ap-tile-config { padding-top: 0; }\n.own-apple .ap-config-copy { display: grid; gap: 12px; justify-items: center; max-width: 640px; }\n.own-apple .ap-config-price { display: flex; align-items: baseline; gap: 6px; margin-top: 8px; }\n.own-apple .ap-config-amount { font-family: var(--font-display); font-size: clamp(40px, 6cqi, 56px); font-weight: 600; letter-spacing: -.28px; }\n.own-apple .ap-config-unit { font-size: 17px; color: var(--ink-muted-48); }\n.own-apple .ap-config-list { list-style: none; display: grid; gap: 8px; font-size: 14px; color: var(--ink-muted-80); margin-top: 10px; }\n.own-apple #apConfigChips { display: flex; flex-wrap: wrap; justify-content: center; gap: 12px; margin-top: 44px; }\n.own-apple .ap-chip { display: flex; flex-direction: column; align-items: center; gap: 4px; min-width: 132px; padding: 16px 18px; border: 1.5px solid var(--hairline); border-radius: var(--r-pill); background: var(--canvas); font-size: 14px; color: var(--ink); transition: border-color .15s; }\n.own-apple .ap-chip:hover { border-color: var(--ink-muted-48); }\n.own-apple .ap-chip[aria-checked=\"true\"] { border-color: var(--primary-focus); border-width: 2px; }\n.own-apple .ap-chip b { font-size: 15px; font-weight: 600; }\n.own-apple .ap-chip span { color: var(--ink-muted-48); }\n\n/* ── footer (dense parchment) ─────────────────────────────────────────────── */\n.own-apple .ap-footer { background: var(--canvas-parchment); padding: 64px var(--gut) 40px; color: var(--ink-muted-80); }\n.own-apple .ap-foot-cols { display: grid; grid-template-columns: repeat(4, 1fr); gap: 24px; max-width: 1180px; margin: 0 auto; }\n.own-apple .ap-foot-col { display: grid; gap: 4px; align-content: start; }\n.own-apple .ap-foot-col h3 { font-size: 14px; font-weight: 600; letter-spacing: -.224px; margin-bottom: 8px; }\n.own-apple .ap-foot-col a { font-size: 12px; line-height: 2.41; color: var(--ink-muted-80); }\n.own-apple .ap-foot-col a:hover { text-decoration: underline; }\n.own-apple .ap-legal { display: flex; align-items: center; justify-content: space-between; gap: 16px; flex-wrap: wrap; max-width: 1180px; margin: 32px auto 0; padding-top: 18px; border-top: 1px solid var(--hairline); font-size: 12px; letter-spacing: -.12px; color: var(--ink-muted-48); }\n.own-apple .ap-legal a { color: var(--primary); }\n.own-apple .ap-legal a:hover { text-decoration: underline; }\n\n/* ── responsive ───────────────────────────────────────────────────────────── */\n@container frame (max-width: 1100px) {\n  .own-apple .ap-global-menu { display: none; }\n  .own-apple #apStoreGrid { grid-template-columns: repeat(3, 1fr); }\n  .own-apple .ap-metric-row { grid-template-columns: repeat(2, 1fr); }\n}\n@container frame (max-width: 760px) {\n  .own-apple .ap-global { top: 0; height: 44px; padding: 0 16px; }\n  .own-apple .ap-subnav { top: 44px; padding: 0 16px; gap: 10px; }\n  .own-apple .ap-subnav-links { display: none; }\n  .own-apple .ap-tile { padding: 48px 16px; }\n  .own-apple .ap-screen-grid { grid-template-columns: 1fr; }\n  .own-apple #apStoreGrid { grid-template-columns: repeat(2, 1fr); }\n  .own-apple .ap-metric-row { grid-template-columns: repeat(2, 1fr); }\n  .own-apple .ap-foot-cols { grid-template-columns: repeat(2, 1fr); }\n  .own-apple .ap-footer { padding: 48px 16px 32px; }\n}\n@container frame (max-width: 430px) {\n  .own-apple .ap-hero { font-size: 34px; }\n  .own-apple #apStoreGrid { grid-template-columns: 1fr; }\n  .own-apple .ap-foot-cols { grid-template-columns: 1fr; }\n  .own-apple .ap-tile-cta { flex-direction: column; }\n}\n@media (prefers-reduced-motion: reduce) {\n  .own-apple *, .own-apple *::before, .own-apple *::after { transition-duration: .001ms !important; animation-duration: .001ms !important; }\n}\n"};
/* ══ NORTHWIND — Apple-language gallery for showcase.html ══════════════════
   Registers window.OWN_LAYOUTS['apple'].init(root). Renders the store grid and
   the configurator chips, keeps the running plan price in sync, and returns a
   cleanup that detaches every listener. */

(function () {
  var OWN = (window.OWN_LAYOUTS = window.OWN_LAYOUTS || {});

  var BOARDS = [
    { name: 'Throughput', sub: '6 lines · Luzon', price: 'Live', val: '412k', ink: '#0066cc', bg: '#eef4fc' },
    { name: 'Line yield', sub: '14 lines · all regions', price: '94.6%', val: '94.6', ink: '#1d7a4b', bg: '#e9f5ef' },
    { name: 'Port ops', sub: '3 berths · Busan', price: '98.1%', val: '98.1', ink: '#b4502a', bg: '#fbeee7' },
    { name: 'Cost per unit', sub: '12 regions', price: '$2.41', val: '2.41', ink: '#6b4ea8', bg: '#f1ecfa' }
  ];

  function esc(s) { return String(s == null ? '' : s).replace(/[&<>"']/g, function (c) { return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]; }); }
  function money(n) { return '$' + Number(n).toLocaleString('en-US'); }

  var BASE = 4700, PER_REGION = 180, INCLUDED = 1;

  OWN['apple'] = {
    init: function (root) {
      var AC = window.AbortController ? new AbortController() : null;
      var signal = AC ? AC.signal : undefined;
      function on(el, type, fn, opt) { if (!el) return; opt = Object.assign({}, opt || {}); if (signal) opt.signal = signal; el.addEventListener(type, fn, opt); }
      function $(s) { return root.querySelector(s); }

      var grid = $('#apStoreGrid');
      if (grid) {
        grid.innerHTML = BOARDS.map(function (b) {
          return '<article class="ap-card">'
            + '<div class="ap-card-photo" style="--ph:' + b.bg + ';--ph-ink:' + b.ink + '"><span>' + esc(b.val) + '</span></div>'
            + '<span class="ap-card-name">' + esc(b.name) + '</span>'
            + '<span class="ap-card-sub">' + esc(b.sub) + '</span>'
            + '<span class="ap-card-price">' + esc(b.price) + '</span>'
            + '<a class="ap-card-link" href="#">Learn more ›</a>'
            + '</article>';
        }).join('');
      }

      var chips = $('#apConfigChips');
      var regions = 3;
      if (chips) {
        chips.innerHTML = [1, 3, 6, 12].map(function (n) {
          return '<button class="ap-chip" type="button" role="radio" data-n="' + n + '" aria-checked="' + (n === regions) + '">'
            + '<b>' + n + ' region' + (n > 1 ? 's' : '') + '</b><span>' + (n === 1 ? 'included' : '+' + money((n - INCLUDED) * PER_REGION) + '/mo') + '</span></button>';
        }).join('');
      }
      function renderPrice() {
        var amt = $('#apAmount');
        if (amt) amt.textContent = money(BASE + Math.max(0, regions - INCLUDED) * PER_REGION);
        if (chips) Array.prototype.forEach.call(chips.children, function (c) {
          c.setAttribute('aria-checked', String(Number(c.dataset.n) === regions));
        });
      }
      on(chips, 'click', function (e) {
        var c = e.target.closest('[data-n]'); if (!c) return;
        regions = Number(c.dataset.n); renderPrice();
      });
      renderPrice();

      return function cleanup() {
        if (AC) { try { AC.abort(); } catch (e) { /* ignore */ } }
      };
    }
  };
})();
